"""Small, conservative JavaScript whitespace/comment minifier."""
import re

def _tokens(s):
    out=[]; i=0; n=len(s)
    while i<n:
        c=s[i]
        if c.isspace():
            if c in '\r\n' and (not out or out[-1] != '\x00NL'): out.append('\x00NL')
            i+=1; continue
        if s.startswith('//',i):
            j=s.find('\n',i+2)
            if j < 0: i=n
            else:
                out.append('\x00NL'); i=j+1
            continue
        if s.startswith('/*',i):
            j=s.find('*/',i+2); end=n if j<0 else j+2
            if s.startswith('/*!',i): out.append(s[i:end])
            i=end; continue
        if c in "'\"`":
            q=c; j=i+1
            while j<n:
                if s[j]=='\\': j+=2; continue
                if s[j]==q: j+=1; break
                j+=1
            out.append(s[i:j]); i=j; continue
        if c.isalpha() or c in '_$' or ord(c)>127:
            j=i+1
            while j<n and (s[j].isalnum() or s[j] in '_$' or ord(s[j])>127): j+=1
            out.append(s[i:j]); i=j; continue
        if c.isdigit() or (c=='.' and i+1<n and s[i+1].isdigit()):
            j=i+1
            while j<n and (s[j].isalnum() or s[j] in '._'): j+=1
            out.append(s[i:j]); i=j; continue
        op=next((op for op in ('===','!==','>>>','**=','=>','==','!=','<=','>=','++','--','&&','||','??','?.','+=','-=','*=','/=','%=','<<','>>','**','...') if s.startswith(op,i)),None)
        if op: out.append(op); i+=len(op)
        else: out.append(c); i+=1
    return out

